-- Original passages for races. Safe to re-run: skips texts that already exist.
insert into public.passages (text)
select t from (values
  ('The quick brown fox jumps over the lazy dog while the rest of the farm sleeps through the warm afternoon.'),
  ('Every great journey begins with a single step, but it is the steady rhythm of the steps after that carries you home.'),
  ('Practice does not make perfect; practice makes permanent, so slow down, type it right, and the speed will follow.'),
  ('The old lighthouse keeper climbed the spiral stairs each evening, counting every step and polishing the brass lamp until it shone like a second moon.'),
  ('Rain tapped against the window in a steady rhythm, and the kettle began to whistle just as the last page of the book was turned.'),
  ('A good map tells you where the roads go, but only curiosity tells you which ones are worth taking on a quiet Sunday morning.'),
  ('The orchestra tuned their instruments in a gentle chaos of notes, then fell silent as the conductor raised a single trembling hand.'),
  ('She planted tomatoes, basil, and a row of sunflowers that grew so tall the neighbours could see them over the garden fence.'),
  ('Computers do exactly what you tell them to do, which is the whole problem when you are not quite sure what you meant.'),
  ('The marathon runner passed the twenty mile mark, ignored the burning in her legs, and focused only on the next lamp post ahead.'),
  ('Fresh bread cooling on a wooden counter fills the whole house with a smell that no candle company has ever managed to copy.'),
  ('On clear winter nights the stars seem close enough to touch, and the cold air makes every breath feel like a small cloud of wonder.'),
  ('The chess player stared at the board for twenty minutes, then moved a single pawn forward and quietly offered his opponent a draw.'),
  ('Our team shipped the update at midnight, celebrated with cold pizza, and spent the next morning fixing the bug we had just introduced.'),
  ('Mountains do not rise without earthquakes, and people rarely grow without facing a few hard days that shake them to the core.'),
  ('The little cafe on the corner served coffee so strong that regular customers swore it could restart a stopped clock.'),
  ('A river carves through solid rock not because of its power but because of its persistence, flowing day after day for thousands of years.'),
  ('The detective noticed the muddy boots by the door, the half finished letter on the desk, and the clock that had stopped at seven.'),
  ('Learning to type quickly is less about moving your fingers fast and more about trusting them to find the right keys without looking.'),
  ('The festival lights flickered on one by one, and the whole town square glowed in shades of orange, gold, and deep crimson red.'),
  ('Penguins cannot fly through the air, yet underwater they glide with such grace that they seem to be flying through a liquid sky.'),
  ('He packed a small bag with a notebook, two pencils, a sandwich, and a map, then walked out the door to find somewhere new.'),
  ('The best ideas often arrive in the shower, on a long walk, or just as you are falling asleep with no pen anywhere nearby.'),
  ('Thunder rolled across the valley, the cattle huddled beneath the oak trees, and the first heavy drops of summer rain began to fall.'),
  ('Writing clean code is like keeping a tidy kitchen; it takes a little effort every day but saves you from a disaster later on.'),
  ('The museum guard had seen every painting a thousand times, yet each morning he still paused in front of the small blue landscape.'),
  ('Bicycles are wonderful machines that turn a person into the most efficient traveller on the planet, at least on flat ground.'),
  ('The baker woke at four, kneaded the dough by lamplight, and had warm rolls on the shelves before the first customer arrived.'),
  ('Waves crashed against the harbour wall as the fishing boats returned, their decks full of silver fish and tired, smiling crews.'),
  ('Time spent reading is never wasted, because every book quietly adds a new room to the house you carry around inside your mind.'),
  ('The astronaut looked back at the blue planet floating in the darkness and realised every border she had known was invisible from here.'),
  ('A gentle breeze carried the scent of jasmine across the courtyard where old friends sat talking long after the sun had set.'),
  ('The robot vacuum bumped into the same chair leg nine times before deciding that the chair was a permanent part of the floor plan.'),
  ('Strong teams are not built from people who never disagree, but from people who disagree honestly and still pull in the same direction.'),
  ('Autumn leaves drifted down in slow spirals, covering the park paths in a crunchy carpet of amber, rust, and bright yellow.'),
  ('The train left the station exactly on time, gliding past sleepy villages, green fields, and rivers that sparkled in the morning light.'),
  ('Good habits are like compound interest; small improvements made every single day add up to remarkable results over a few years.'),
  ('The magician pulled a coin from behind the child''s ear, and for one perfect moment the whole room believed that anything was possible.'),
  ('Snow fell silently all night, and by morning the city had been transformed into a hushed white world of soft edges and bright light.'),
  ('When the power went out, the family lit candles, played cards at the kitchen table, and laughed more than they had in weeks.')
) as v(t)
where not exists (select 1 from public.passages p where p.text = v.t);
